        obj.__dict__[self.name] = value

class Config:
    api_key = FinalAttribute()

c = Config()
c.api_key = 'secret123'
try:
    c.api_key = 'newsecret'
except AttributeError:
    print(c.api_key)

class ClassProperty:
    def __init__(self, fget):
        self.fget = fget

    def __get__(self, obj, objtype=None):
        if objtype is None:
            objtype = type(obj)
        return self.fget(objtype)

class Service:
    _instances = 0

    @ClassProperty
    def count(cls):
        return cls._instances

    def __init__(self):
        Service._instances += 1

Service()
Service()
print(Service.count)

class ContextLocal:
    _storage = {}

    def __init__(self):
        self._key = id(self)

    def __enter__(self):
        ContextLocal._storage[self._key] = {}
        return ContextLocal._storage[self._key]

    def __exit__(self, *args):
        del ContextLocal._storage[self._key]

cl = ContextLocal()
with cl as ctx:
    ctx['value'] = 42
    print(ctx['value'])
print(cl._key in ContextLocal._storage)

class AttributeGuard:
    def __init__(self, allowed):
        self.allowed = allowed

    def __set_name__(self, owner, name):
        self.name = name

    def __get__(self, obj, objtype=None):
        if obj is None:
            return self
        return obj.__dict__.get(self.name, None)

    def __set__(self, obj, value):
        if value not in self.allowed:
            raise ValueError(f'Value must be one of {self.allowed}')
        obj.__dict__[self.name] = value

class TrafficLight:
    color = AttributeGuard(['red', 'yellow', 'green'])

tl = TrafficLight()
tl.color = 'green'
try:
    tl.color = 'blue'
except ValueError:
    print(tl.color)
